mapper.select:

where t.del_flag = '0'
and t.name like concat('%', #{name}, '%')
and t.status = #{status}
and p.country_id = #{countryId}
and c.province_id = #{provinceId}
and t.city_id = #{cityId}
and t.create_time >= #{beginCreateTime}
and t.create_time < #{endExclusive}
order by t.sort desc, t.id desc
